import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易尚氏学 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易尚氏学 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/044.md","filePath":"zh/classics/shangshi/044.md"}'),h={name:"zh/classics/shangshi/044.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>重坎故日蹇。坤在西南。五往居坤中。得中有应。放曰利西南。艮居东北。三阳穷于上而多凶。故不利东北。大人谓五。往得尊位。故利于出见。传所谓往有功也。往五当位居中。故贞吉。</p><p>彖曰。蹇。鸡也。险在前也。见险而能止。知矣哉。蹇利西南。往得中也。不利东北。其道穷也。利见大人。往有功也。当位员吉。以正邦也。蹇之时用大矣哉。</p><p>坎险又止。故曰见险而能止。此卦义也。虞翻于利不利之故。盖茫然莫解。复以参同契月出庚之说。解利西南。月灭癸之说。解不利东北。岂知兹所谓西南确指坤位。坤为邦。五居坤中。故曰正邦。而翻则曰月生西南。夫月于三日出庚。庚岂西南哉。真管辂所谓美而伪也。</p><p>象曰。山上有水。蹇 君子以反身修德。</p><p>见险而止。反身修德。以俟之而已。文言云。进德修业。乾三云。君子终日乾乾夕惕若。修德之事也。艮为身。反身者反而求诸己。不徒止而不前也。艮身象。艮彖云。艮其背不获其身。以艮为身也。故易林需之坎云。名困身辱。劳无所得。坎中爻艮。艮为名。为身。坎隐伏。故名困身辱。虞翻用卦变。以坤为身。不知艮亦为身也。</p><p>初六。往黎。来誉。</p><p>四不应。二至四坎。初临之。故往蹇。来居初。静而不动。则有誉也。又为名。故曰誉。</p><h3 id="象曰。往蹇来誉。宜时也。" tabindex="-1">象曰。往蹇来誉。宜时也。 <a class="header-anchor" href="#象曰。往蹇来誉。宜时也。" aria-label="Permalink to “象曰。往蹇来誉。宜时也。”">​</a></h3><p>宜时。正义作宜待。释文云。张氏作宜时。郑本作宜待时。虞同。兹从张氏。艮为时。宜时者。谓时宜如此也。阮校云。石经待也二字。漫漶。而不言上有宜宇。可见郑虞读似非。</p><p>六二。王臣蹇蹇。匪躬之故。</p><p>艮为臣。五为王。二应五。故曰王臣。艮为憧仆。古臣仆不分。故艮亦为臣。二临重坎。故曰王臣蹇蹇。蹇蹇言劬劳也。艮为躬。匪躬之故。言所以劬劳如此者。乃从王事。匪为私也。艮臣象。损上九云。得臣无家。小过六二云。遇其臣。遁六三云。畜臣妾吉。皆以艮为臣也。</p><h3 id="象曰。-王巨蹇蹇。终无尤也。" tabindex="-1">象曰。 王巨蹇蹇。终无尤也。 <a class="header-anchor" href="#象曰。-王巨蹇蹇。终无尤也。" aria-label="Permalink to “象曰。 王巨蹇蹇。终无尤也。”">​</a></h3><p>有应故无尤。尤古音信。诗部风大夫君子。无我有尤。与下之协。此与上时下之协。与诗同。故正义上象作宜待非。</p><p>九三。往蹇。来反。</p><p>往遇险。反据下二阴则利也。故曰往蹇来反。</p><h3 id="象曰。往蹇来反。内喜之也。" tabindex="-1">象曰。往蹇来反。内喜之也。 <a class="header-anchor" href="#象曰。往蹇来反。内喜之也。" aria-label="Permalink to “象曰。往蹇来反。内喜之也。”">​</a></h3><p>内谓下二阴。阴欲承阳。故曰内喜之。释来反之故也。</p><p>六四。往蹇。来连。</p><p>正义。马云连亦难也。王弼云。往来皆难。是亦训连为难。盖四居上下坎之间。故往来皆难。荀爽谓与至尊相连。朱子谓连于九三者皆非也。又屯上六云。泣血涟如。淮南子引作连如。盖与此义同。亦连为难之一证。</p><h3 id="象曰。往蹇来连。当位实也。" tabindex="-1">象曰。往蹇来连。当位实也。 <a class="header-anchor" href="#象曰。往蹇来连。当位实也。" aria-label="Permalink to “象曰。往蹇来连。当位实也。”">​</a></h3><p>坎为实。当位实者。言四位当。惟所值上下皆实。故进退难也。坎刚中故为实。易林屯之师云。李梅冬实。师震为李梅。坎为冬为实也。旧解皆以乾为实。致此句义不明了。岂知此宾字谓坎。上下坎。方能明来往皆难之义也。</p><p>九五。大蹇。用来。</p><p>当位居尊。故曰大蹇。阴以阳为朋。阳往阴中。故曰朋来。虞翻以下卦伏兑为朋。岂知象传曰中节。即谓五居坤中。如合符节。释朋义也。</p><h3 id="象曰。大蹇朋来。以中节也。言五在阴中。阴阳相遇。如符节之合。" tabindex="-1">象曰。大蹇朋来。以中节也。言五在阴中。阴阳相遇。如符节之合。 <a class="header-anchor" href="#象曰。大蹇朋来。以中节也。言五在阴中。阴阳相遇。如符节之合。" aria-label="Permalink to “象曰。大蹇朋来。以中节也。言五在阴中。阴阳相遇。如符节之合。”">​</a></h3><p>上六。往蹇。来硕。吉。利见大人。</p><p>上穷故往蹇。来硕谓应三。三阳故曰硕。尔雅释诂。硕大也。阳大故曰硕。利见大人。谓顺五。五为大人。</p><h3 id="象曰。往蹇来顶。志在内也。利见大人。以从贵也。" tabindex="-1">象曰。往蹇来顶。志在内也。利见大人。以从贵也。 <a class="header-anchor" href="#象曰。往蹇来顶。志在内也。利见大人。以从贵也。" aria-label="Permalink to “象曰。往蹇来顶。志在内也。利见大人。以从贵也。”">​</a></h3><p>应三故曰在内。三体坎。故曰志在内。五天子位。故曰从贵。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
